#!/usr/bin/env python3
"""Generates src/shared/DecorAssets.luau from assets_decor.json (the decor model ids in Roblox). Do not edit by hand.
    python3 write_decor_assets.py
"""
import json
import os

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)
st = json.load(open(os.path.join(ROOT, "assets_decor.json")))
lines = ["--!strict", "-- Generated by tools/write_decor_assets.py from assets_decor.json (Kenney Nature Kit 2.1, CC0; split by materials).",
         "-- id = 0: the model is not uploaded, Decor skips the kind. Do not edit by hand.", "", "return {"]
n = 0
for name in sorted(st):
    v = st[name]
    if not name.startswith("decor_"):
        continue
    kind = name[len("decor_"):]
    aid = v.get("assetId") or 0
    if v.get("moderation") not in (None, "Approved"):
        aid = 0
    lines.append(f"\t{kind} = {aid},")
    n += 1 if aid else 0
lines.append("}")
open(os.path.join(ROOT, "src", "shared", "DecorAssets.luau"), "w", encoding="utf-8").write("\n".join(lines) + "\n")
print(f"DecorAssets.luau: {n} models with an id")
